-- 为已建好的表补自增主键（PostgreSQL identity 列）
-- 在 Neon SQL Editor 中整段执行一次即可，重复执行会报 "already an identity column"

ALTER TABLE public.sys_user               ALTER COLUMN sys_user_id               ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.source_document        ALTER COLUMN source_document_id        ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.question               ALTER COLUMN question_id               ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.question_choice        ALTER COLUMN question_choice_id        ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.question_blank         ALTER COLUMN question_blank_id         ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.question_judge         ALTER COLUMN question_judge_id         ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.question_short_answer  ALTER COLUMN question_short_answer_id  ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.question_comprehensive ALTER COLUMN question_comprehensive_id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.paper                  ALTER COLUMN paper_id                  ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.paper_part             ALTER COLUMN paper_part_id             ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.paper_question         ALTER COLUMN paper_question_id         ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.exam_record            ALTER COLUMN exam_record_id            ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.exam_answer            ALTER COLUMN exam_answer_id            ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.wrong_question         ALTER COLUMN wrong_question_id         ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.generation_task        ALTER COLUMN generation_task_id        ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.ai_chat_message        ALTER COLUMN ai_chat_message_id        ADD GENERATED BY DEFAULT AS IDENTITY;
